sha=822b319207a3b8216f93fb1e5a2bfe0b7583c734
while true; do
  resp=$(curl -sS -H "Authorization: Bearer $GITHUB_TOKEN" -H "Accept: application/vnd.github+json" \
    "https://api.github.com/repos/missingbulb/CrosswordChat/commits/$sha/check-runs" || true)
  echo "$resp" | node -e '
    let data = "";
    process.stdin.on("data", d => data += d);
    process.stdin.on("end", () => {
      try {
        const j = JSON.parse(data);
        const runs = j.check_runs || [];
        if (!runs.length) { console.log("no check runs yet"); return; }
        for (const r of runs) {
          console.log(`${r.name} #${r.id}: status=${r.status} conclusion=${r.conclusion}`);
        }
        const allDone = runs.every(r => r.status === "completed");
        if (allDone) console.log("ALL_DONE");
      } catch (e) { console.log("parse-error " + e.message); }
    });
  '
  if echo "$resp" | grep -q '"status":"completed".*"status":"completed"\|"status": "completed"'; then :; fi
  done_check=$(echo "$resp" | node -e '
    let data = "";
    process.stdin.on("data", d => data += d);
    process.stdin.on("end", () => {
      try {
        const j = JSON.parse(data);
        const runs = j.check_runs || [];
        console.log(runs.length > 0 && runs.every(r => r.status === "completed") ? "yes" : "no");
      } catch(e) { console.log("no"); }
    });
  ')
  if [ "$done_check" = "yes" ]; then break; fi
  sleep 20
done
echo "MONITOR_COMPLETE"

